import{_ as r,a0 as o,w as i,s as u,I as n,x as a,a1 as p,A as s,ao as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const g=JSON.parse(`{"title":"KDE Plasma 5 —— 給尚未確定桌面環境的 Linux 用户指明道路 | LCTT x X-CMD","titleTemplate":false,"description":"KDE Plasma 5 —— 給尚未確定桌面環境的 Linux 用户指明道路 | LCTT (201409) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"KDE Plasma 5 —— 給尚未確定桌面環境的 Linux 用户指明道路 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"KDE Plasma 5 —— 給尚未確定桌面環境的 Linux 用户指明道路 | LCTT (201409) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201409/20140819 KDE Plasma 5--For those Linux users undecided on the kernel' s future","title":"KDE Plasma 5 —— 給尚未確定桌面環境的 Linux 用户指明道路","tag":"201409","desc":""},"relativePath":"201409/20140819 KDE Plasma 5--For those Linux users undecided on the kernel' s future.md","filePath":"[post].md"}`),m={name:"201409/20140819 KDE Plasma 5--For those Linux users undecided on the kernel' s future.md"};function d(E,e,D,K,P,k){const t=o("Link");return i(),u("div",null,[e[26]||(e[26]=n("h1",{id:"kde-plasma-5-——-給尚未確定桌面環境的-linux-用户指明道路",tabindex:"-1"},[a("KDE Plasma 5 —— 給尚未確定桌面環境的 Linux 用户指明道路 "),n("a",{class:"header-anchor",href:"#kde-plasma-5-——-給尚未確定桌面環境的-linux-用户指明道路","aria-label":"Permalink to “KDE Plasma 5 —— 給尚未確定桌面環境的 Linux 用户指明道路”"},"​")],-1)),e[27]||(e[27]=n("blockquote",null,[n("p",null,"點評 ———— 新的KDE 5版本既滿足了傳統桌面環境的需求，也兼顧了多設備長期支持計劃")],-1)),e[28]||(e[28]=n("p",null,"KDE 項目終於發佈了備受矚目的 KDE 桌面環境的最新主版本 ———— KDE Plasma 5。",-1)),e[29]||(e[29]=n("p",null,"Plasma 5 站在了一場正在進行的未來 Linux 桌面環境的爭奪戰中間。",-1)),n("p",null,[e[1]||(e[1]=a("一方面，有着 GNOME 和 Unity 這樣的新生桌面代表。二者均通過某種重要方法打破了傳統桌面模式的壟斷，並且都不只是滿足於桌面型計算機，而將其界面延伸到了備受期待的新型平板電腦（",-1)),p(t,{href:"http://arstechnica.com/gadgets/2014/08/op-ed-tables-really-are-pcsbecause-theres-no-point-in-buying-new-ones/"},{default:s(()=>[...e[0]||(e[0]=[a("也許不久後就會面世",-1)])]),_:1}),e[2]||(e[2]=a("）。",-1))]),e[30]||(e[30]=l('<p>另一方面，Linux 桌面環境，如 KDE、XFCE、LXDE、Mate 甚至 Cinnamon，都是桌面環境的另一種類型 ———— 自發布以來沒有什麼大的變化，繼續向用户提供傳統的桌面環境體驗，但這並不能表明這些項目沒有成長和進步。這些發行版全部持續更新，並且根據成熟桌面應有的模式進行了不斷的調整。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/08/screenshot-unity.png" alt="Ubuntu 下的 Unity 桌面環境"></p><p>Ubuntu 下的 Unity 桌面環境</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/08/screenshot-gnome.png" alt="GNOME 3 桌面環境"></p><p>GNOME 3 桌面環境</p><p>GNOME 和 Unity 暫時在這場正在進行的爭奪戰中贏得了最大的優勢。二者均新穎非凡，固執並極端。有的 Linux 用户對他們情有所鍾，也有的 Linux 用户對他們恨之入骨。這使得在 Linux 世界裏，沒有哪條關於這兩個桌面環境的評論或帖子是輕鬆活潑的。同時兩大 Linux 陣營之間的差異不僅僅關乎於你未來桌面的樣子，更決定了未來計算機會如何運作。</p><p>GNOME 和 Unity 相信未來的計算機運作方式，是由多台設備同時運行着相同的軟件互相合作而成的 ———— 因此這兩個項目發行的新版桌面只朝着這個方向努力。這些新版桌面並不是真正意義上作為未來桌面打造的，而是同時囊括了現在意義上的桌面，以及會出現在未來設備上的桌面的混合桌面。而另一派 Linux 桌面環境似乎完全忽視了這些。</p><p>與閉源操作系統的世界不同 ———— 那裏所有變化都遺傳了下來，與之仿效還是以之為戒？Linux 世界正在這兩種對立的觀點中徘徊着。</p><p>對用户羣體來説，這也許很令他們沮喪。試想你正在努力完成工作，但此時你必須完成一個會徹底改變你現有桌面環境的更新，陌生的工作方式使你不得不花費時間來學習。即便最好的情況是，當你曾經最喜愛的桌面環境更新得面目全非的時候，你選擇遷移到了其他桌面去。但你長久以來的使用習慣以及那種熟悉的感覺，卻再也無法找回了。</p><p>幸運的是，有一個簡單的方法去避免這種糟糕的情況併為你找到合適的桌面。簡而言之：你想被桌面牽制，還是想控制桌面？</p><p>如果你是第一派陣營的，並且樂於學習新的工作方式，那麼 Unity 和 GNOME 3 將會是你最好的選擇。如果你是後一派陣營的，XFCE、Cinnamon、Mate，還有許多其他的桌面環境，都將很好的滿足你的需求。甚至如果你想嘗試和 Unity 還有 GNOME 3 都不相同的新生桌面時，也有 Xmonad、Ratpoison 等其他非常小眾的桌面環境供你選擇。（説來慚愧，自從 Linus 説了“呃，嘿，這有個內核非常適合你的 GNU 操作系統”以來，Xmonad 可能是 Linux 裏最好的東西了。）</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/08/screenshot01.png" alt="KDE Plasma 5&#39;s new boot screen."></p><p>KDE Plasma 5 的啓動界面</p><p>那麼對於猶豫不決的 Linux 用户呢，讓他們隨便選一種嗎？他們喜歡傳統桌面環境的帶來體驗，但也不想因此放棄新生桌面的菜單、快捷方式還有任務欄，同時他們還擔心着平板電腦等其他問題，想着是否會有某個桌面能在所有設備上工作。假如你正在這麼想，那麼我的朋友，你絕對有必要嘗試下 KDE 的最新版 Plasma 5。</p><p>KDE 正在嘗試做其他 Linux 桌面都沒有做過的事 ———— 向平板電腦及移動設備桌面前進的同時，繼續向用户提供傳統的、多功能的、高度定製化的桌面體驗。</p><h3 id="kde-plasma-5-與-通用-世界" tabindex="-1">KDE Plasma 5 與“通用”世界 <a class="header-anchor" href="#kde-plasma-5-與-通用-世界" aria-label="Permalink to “KDE Plasma 5 與“通用”世界”">​</a></h3><p>經歷過 KDE 3.5 升級至 KDE 4 的用户似乎仍然避免任何有關 KDE 的重要更新，但對 KDE 粉絲而言，Plasma 5 還是帶來了一些好消息。確實這是一個重要更新，沒錯，但這只是極少數情況下出現的例外（因此我得花費點時間來解釋一下，因為你還不太瞭解）。</p><p>事實證明，難以置信且艱難萬分的 KDE 4 更新確實為一個更加美好的未來打下了堅實的基礎 ———— 我們現在剛剛抵達這美好的未來。</p><p>通過這次更新，KDE 核心今後出現變化的可能性大大減小。我們確實提及了正邁向平板電腦以及其他設備的一步，這令人難以置信，但不要害怕。KDE 似乎準備去做 GNOME 和 Unity 無法做到的事 ———— 在不改變傳統桌面模式的前提下，移植到其他設備上去。換言之，這一版本極力避免了所有因某些新技術的出現而隨意嘗試所導致的混亂結果。</p><p>（説點其他的：如果你沒記住也沒關係，但你認同 Canonical 繼續通過 Unity 的更新來實現桌面通用這件事嗎？早在 Canonical 讓用户測試 GNOME 2 菜單中的陰影棕色以調配出最佳效果時，KDE 就開始決定實施桌面統一計劃了）</p><p>通過 KDE Frameworks 5、Qt5 還有其他一系列隨同 Plasma 5 進行的更新，通用版本的 KDE 得以實現。KDE 將出現在任何需要它的地方。</p>',21)),n("p",null,[e[4]||(e[4]=a("因此當所有因素出現時，KDE 項目及其開發者打造出了全新的界面 ———— KDE 稱這種新框架為“通用等離子殼層”（converged Plasma shell），在 Plasma 5 中作為支撐桌面環境的框架基礎 ———— Plasma 5 桌面截至目前，是唯一的界面。KDE 計劃打造出其他的界面，但針對 Plasma 5 的",-1)),p(t,{href:"http://www.kde.org/announcements/plasma5.0/"},{default:s(()=>[...e[3]||(e[3]=[a("官方聲明",-1)])]),_:1}),e[5]||(e[5]=a("中提到“一個平板中心及用户體驗媒體中心正在開發中”。",-1))]),e[31]||(e[31]=l('<p>從這點來看，KDE 的通用版本和和 Ubuntu 所預想的並不相同；用户界面將基於設備和硬件進行改變。例如，當你在長椅上瀏覽網頁的時候，你也許有台平板電腦正在管理着進行中的工作。然後你起身，走回辦公室，連接無線鍵盤，平板電腦又變成了擁有鍵盤的友好操作界面。</p><p>這種情況下有些潛在的問題，部分 Win 8 用户也許已經習以為常了。比方説，假如鍵盤正在進行輸入，而你仍然想通過觸屏進行交互，會發生些什麼？試想你正在操縱鼠標，但你同時卻想活動活動手指。</p><p>我們提及這些並不是説 KDE 沒有考慮過這些問題（希望他們已經考慮過了），而是指這個“通用”所有設備用户界面的想法將很難做到完美。並且 KDE 一直在做一件事 ———— 暗示用户這項計劃的成功是遙遙無期的。</p><p>假如 KDE 能運行在平板設備上，那麼用户將獲得可以訂製任何細節部分的體驗。簡單來説，會有一種方法讓你決定當系統檢測到鍵盤時進行什麼操作，而不是讓系統自己決定。</p><h3 id="plasma-5-桌面" tabindex="-1">Plasma 5 桌面 <a class="header-anchor" href="#plasma-5-桌面" aria-label="Permalink to “Plasma 5 桌面”">​</a></h3><p>KDE Plasma 5 是由 KDE 4 演化來的，而不是任何一種意義上的界面革新。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/08/screenshot02.png" alt="KDE Plasma 5 的桌面。"></p><p>KDE Plasma 5 的桌面。</p><p>我們早就用這個版本了 ———— 早在不太穩定的測試期時就開始了，儘管大部分錯誤提示已圖形化，而不僅僅是文字警告 ———— 截至目前已在虛擬機上運行了超過一個月的時間。我們已經在 Retina 屏的 MacBook Pro 上進行過了雙重啓動測試，並且驗證了 KDE 在更舊的硬件，一台古老的東芝筆記本上，表現如何。測試 KDE Plasma 5 期間我們使用了 Kubuntu（虛擬機和東芝筆記本）以及新安裝的 Arch Linux（MacBook 上的雙重啓動）。</p>',9)),n("p",null,[e[7]||(e[7]=a("如果你想試試 Plasma 5，最簡單的方法是下載",-1)),p(t,{href:"http://files.kde.org/snapshots/neon5-latest.iso.mirrorlist"},{default:s(()=>[...e[6]||(e[6]=[a("KDE 的官方 Neon live CD",-1)])]),_:1}),e[8]||(e[8]=a("。這樣可以使你得到在 Ubuntu 上運行的 Plasma。如果你想在一個已經安裝了 Kubuntu 的操作系統上安裝測試，你可以使用以下命令：",-1))]),e[32]||(e[32]=l(`<pre><code>sudo add-apt-repository ppa:neon/kf5
sudo apt-get update
sudo apt-get install project-neon5-session project-neon5-utils project-neon5-konsole project-neon5-breeze project-neon5-plasma-workspace-wallpapers
</code></pre><p>重啓你的機器，你將會在登錄界面下找到啓動 Neon 的新啓動項。</p><p>當你安裝完 Plasma 5 並且啓動時，首先你將會注意到的是叫做 Breeze 全新 KDE 默認主題。</p><h3 id="plasma-5-的全新外觀-breezy" tabindex="-1">Plasma 5 的全新外觀 Breezy <a class="header-anchor" href="#plasma-5-的全新外觀-breezy" aria-label="Permalink to “Plasma 5 的全新外觀 Breezy”">​</a></h3><p>Breezy 主題是 KDE 所要呈現出的一種現代化界面，同時“減少了工作區的視覺混亂”。也就是説，很長時間以來一直作為 KDE 默認外觀一部分的，那種給人以忙碌混亂的感覺已經成為了過去。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/08/screenshot03.png" alt="KDE Plasma 5 的 Breeze 桌面主題最大程度上完善了開始菜單。每個標籤下都有註釋，方便搜索。"></p><p>KDE Plasma 5 的 Breeze 桌面主題最大程度上完善了開始菜單。每個標籤下都有註釋，方便搜索。</p><p>全部界面發生了極大的變化 ———— 更大的字體，更好的對比度，以及一種全新的平面佈局，其“磨砂”外觀有點類似並且介於 OS X Yosemite、Android L 還有 KDE 4.x 的風格。這並不是説 KDE 抄襲了蘋果或者谷歌。這不可能是抄襲，因為 Plasma 5 和 Breeze 主題發佈了很長時間之後蘋果核谷歌那裏才透漏出些許 Yosemite 還有 Android L 的信息出來。</p><p>當然，説 KDE 抄襲了任何產品都是不對的，從 Breeze 的視覺設計和整體審美性來看，其更偏向於長時間沉澱的作品。從這種角度看，它看起來很“現代化”，只要你把現代化定義為較多的尖鋭元素，較少的紋理和輪廓，更多的半透感，以及單色圖形。</p><p>KDE 的設計者將大量的工作放在了 Breeze 主題還有其外觀上。這不僅僅是外觀上的變化。Breeze 主題藉由清爽的菜單、更有條理的通知中心以及全新的開始菜單，使 KDE 變得更加友好。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/08/screenshot04.png" alt="清爽、有條理的通知中心。"></p><p>清爽、有條理的通知中心。</p><p>Breeze 出現了多少問題取決於你是否使用過它。KDE 更傾向於那些喜歡定製自己系統的用户，他們大概也喜歡定製主題。有件期待的事，有什麼發行版會大幅修改默認 KDE 主題？ ———— 顯然是 OpenSUSE ———— 將會提供一個比 Breeze 所提供的更高的開始菜單欄。</p><p>目前而言，大多數發行版應該不會直接過渡到 Breeze 上去，因為其仍處於測試階段。而且巧合的是，Breeze 將會是你注意到 Plasma 5 不完美的第一個標誌。開始菜單上有許多很棒的新圖標了，但其他界面上卻沒有。並且作為 Kubuntu PPA 可用的最新更新，Breeze 並未使用新版的窗口裝飾。新版窗口裝飾是已經安裝了的，但默認並未被使用。你可以去系統設置中打開該選項以獲得更完整的，但也更有可能出 bug 的 Breeze 體驗。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/08/screenshot05.png" alt="圖片上半部分是默認的 Oxygen 窗口裝飾，下半部分是最新的 Breeze 主題中的窗口裝飾。"></p><p>圖片上半部分是默認的 Oxygen 窗口裝飾，下半部分是最新的 Breeze 主題中的窗口裝飾。</p><p>並非所有都是理想的，有時很難分辨什麼是 bug 或者什麼地方是不完善的，以及哪裏的設計不夠好。比如，Breeze 下有很多窗口的時候會呈半透明覆蓋狀，其中一些看起來非常好看。但某些時候，這會成為一種妨礙。堆疊窗口與覆蓋預覽之後的是什麼，在後台時很難看到這些。可以通過將之拉至前台來解決問題，但這樣一來則很難評價透明的意義在哪裏。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/08/screenshot06.png" alt="透明... 意義何在？"></p><p>透明... 意義何在？</p><p>是的，Breeze 主題仍然處於測試中，不僅僅是功能和設計；工作重點放在了真正 bug 還有缺陷上。同時我們還遇到了一些意料之外的情況，特別是關於屏幕刷新的問題。這些問題頻繁發生，很長時間才引起我們的注意。窗口時常消失，並且有時菜單欄只顯示一半。</p><p>Plasma 5 在我們的測試期間從未崩潰過，並且從未遺失任何數據。但注意 ———— 經常會有一些圖像方面的小 bug 出現。我們建議你在穩定版發佈前不要嘗試進行更新。</p><h3 id="plasma-的垂直菜單" tabindex="-1">Plasma 的垂直菜單 <a class="header-anchor" href="#plasma-的垂直菜單" aria-label="Permalink to “Plasma 的垂直菜單”">​</a></h3><p>Breeze 給 Plasma 5 帶來一種新外觀，同時也帶來了許多細節方面的變化。例如，窗口小部件和 ALT-TAB 窗口切換均呈現垂直顯示，並且默認都具有相同的啓動位置 ———— 當前屏幕的左側。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/08/screenshot07.png" alt="ALT-TAB 窗口切換的默認外觀。"></p><p>ALT-TAB 窗口切換的默認外觀。</p><p>共通性也許對於 KDE 的新特點是有利的，當需要幫助時所需資料會出現在屏幕的左側，但這也許會對那些期待點其他東西的老用户感到失望。有些變化看上去不太合情理。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/08/screenshot08.png" alt="窗口小部件。"> 窗口小部件。</p><p>KDE 項目稱在像窗口小部件和窗口切換器等菜單中，垂直菜單將取代水平菜單，“提供更好的使用體驗”。但並未提及會具體如何。發行文檔稱挪動窗口切換器至屏幕一端“使用户的注意力更加集中於應用和文檔，以完成手頭上的工作”。可是當你啓用了窗口切換器，嗯，準備切換窗口時，你的注意力更可能是在不同的任務間而不是集中在某一個任務上面。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/08/screenshot09.png" alt="KDE 依舊偏向於提供不同選擇。注意右側的暗灰色選擇條，那是拖動窗口時的陰影選項。"></p><p>KDE 依舊偏向於提供不同選擇。注意右側的暗灰色選擇條，那是拖動窗口時的陰影選項。</p><p>這就是 KDE，當然，不是 Unity；高度可定製化是其一大特色，而不是 bug。進入系統設置你可以調回舊版風格的窗口切換器，並且在 Plasma 5 中有 10 種不同的窗口切換器效果可供選擇。如果默認風格並不是你最喜歡的，那麼換一個吧。</p><h3 id="告別-nepomuk-語義桌面的時間-感謝長久以來支持着我們的粉絲" tabindex="-1">告別 Nepomuk 語義桌面的時間，感謝長久以來支持着我們的粉絲 <a class="header-anchor" href="#告別-nepomuk-語義桌面的時間-感謝長久以來支持着我們的粉絲" aria-label="Permalink to “告別 Nepomuk 語義桌面的時間，感謝長久以來支持着我們的粉絲”">​</a></h3><p>如果你是 KDE 重度用户，並且經歷了 KDE 的頂峯和低谷，並仍抱有期待，那麼你肯定已經知道了 Plasma 5 中的最大看點。沒錯，KDE 替換了 Nepomuk 語義桌面，取而代之的是稱作 Baloo 的新搜索引擎。</p><p>Nepomuk 語義桌面最初是一個由歐盟贊助的搜索項目，高調宣稱其目的是創建一個“使用網絡環境提供個性化服務的，基於本地的知識庫管理(Networked Environment for Personalized, Ontology-based Management of Unified Knowledge)”。當項目被引用到 KDE 上的時候，Nepomuk 成為了一個更加通用的桌面搜索工具，在輝煌與瘋狂之間徘徊着。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/08/screenshot10.png" alt="在 Plasma 5 中搜索文件。"></p><p>在 Plasma 5 中搜索文件。</p>`,36)),n("p",null,[e[10]||(e[10]=a("Baloo 沿用了 Nepomuk 的大部分功能，全文字文件搜索和一種不可思議的文件銜接功能，比如，知曉與一個特定文件相關的其他文件並",-1)),p(t,{href:"https://dot.kde.org/2014/02/24/kdes-next-generation-semantic-search"},{default:s(()=>[...e[9]||(e[9]=[a("予之改進",-1)])]),_:1}),e[11]||(e[11]=a("。實際上這使用於 Plasma 5 中的搜索功能，並且你可以在搜索欄的右邊注意到兩點：更快的速度以及每次索引更新時你的風扇並未發瘋般狂轉。",-1))]),e[33]||(e[33]=l('<p>Baloo 大幅減少了搜索記錄的資源，並且，根據 KDE 上的測試，其準確度更高了。我們不能保證後一點，因為我們從未在舊版 KDE 中使用大量搜索（參見風扇運轉註釋），但在計算精度上，Plasma 5 中的簡單文件搜索達到了你使用 Ubuntu、OS X 等其他文件搜索方式的平均速度。涉及更復雜的搜索關係或複雜元數據的成功將更大程度上取決於你使用默認 KDE 應用的頻率。比方説，如果你想利用基於 Baloo 的搜索引擎的優勢進行涉及文件間關聯的搜索時，你需要使用 Kontact 套件。</p><p>儘管這肯能會隨着時間而改變，因為與 Nepomuk 相比另一個比較大的變化是新的、改進的開發者 API。搜索 API 意味着第三方應用可以配合 Plasma 5 中的語義搜索基礎，併發揮默認應用所使用的相同工具的優勢。</p><p>奇怪的是，其他可見的和 Baloo 具有相同任務量的搜索工具，其可見度與發掘性已經落後一步了。點燃 Plasma 5 的開始菜單 ———— KDE 對窗口開始菜單的回應 ———— 並且無法找到搜索欄。如果你仔細尋找，你將會找到一個非常小的提醒樣式的“點擊以進行搜索”，這是初版以來的第一步改變（沒有你可以進行搜索的指示）。然而，可以發現這並不是一個專門的搜索框。</p><h3 id="kickoff-開始菜單與他的新表弟-kicker" tabindex="-1">Kickoff 開始菜單與他的新表弟 Kicker <a class="header-anchor" href="#kickoff-開始菜單與他的新表弟-kicker" aria-label="Permalink to “Kickoff 開始菜單與他的新表弟 Kicker”">​</a></h3><p>KDE 提交的關於窗口開始菜單的答案一直是過度包裝的、狹小空間內擁擠的視覺外觀，但在 Breeze 主題中開始菜單開始變得清爽，並更具有視覺觀賞性。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/08/screenshot11.png" alt="默認主題下的開始菜單。"></p><p>默認主題下的開始菜單。</p><p>如果這樣對你的需求來説還是有點多，Plasma 5 提供了一個全新的、更加傳統的菜單 ———— 稱為 Kicker，基於原啓動器。Kicker 所需完成的任務更少 ———— 它更接近於 XP 中的開始菜單，在需要提供擴展菜單的地方提供一種單一的、狹窄的面板 ———— 並且在你如果只是想啓動應用或打開文件時，提供一種更加輕量級的選擇。它也有一個非常顯眼的搜索框。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/08/screenshot12.png" alt="另一個選擇 ———— 全新的 Kicker 菜單。"></p><p>另一個選擇 ———— 全新的 Kicker 菜單。</p><p>菜單的另一側得到了更新，變得更加清爽。最顯著的變化是通知中心，減少了彈出次數，並且通過更好、更迅速方式來顯示通知。</p><h3 id="opengl、qtquick-以及-hidpi-顯示" tabindex="-1">OpenGL、QtQuick 以及 HiDPI 顯示 <a class="header-anchor" href="#opengl、qtquick-以及-hidpi-顯示" aria-label="Permalink to “OpenGL、QtQuick 以及 HiDPI 顯示”">​</a></h3><p>Plasma 5 完成了 KDE 至 Qt 5 和 QtQuick 的遷移，後者使用硬件加速的 OpenGL 場景圖進行圖形渲染。OpenGL 的大部分更新都和任何可用的 GPU 圖形卸載有關。這意味着，如果你擁有被支持的硬件，Plasma 5 將利用現今強勁的 GPU 充分發揮顯卡優勢。</p><p>事實上，在最新的硬件上（例如我們測試所用的 MacBook 的 NVIDIA GeForce GT 顯卡）Plasma 5 的反應速度很迅捷，遠比其老版本要快。也許更令人印象深刻的是，即使把 Plasma 5 相比 KDE 4.x 在 GPU 上的優勢去除，其反應速度仍然很快。也就是説，雖然在老舊硬件上運行仍然不是 KDE 的強項，但其表現與之前相比已有所改觀。不過，如果你想在老舊硬件上得到更多支持，請務必使用 Xfce、LXDE 或者某些像 Openbox 那樣簡單的桌面環境吧。</p><p>有趣的是，彌補 Plasma 5 圖形疊加的修改過後的框架也向 KDE 切換至 Wayland 顯示服務協議提供了道路。儘管 KDE 並沒有急着切換到 Wayland，但注意全面支持技術將在“某個未來版本”實現。</p><p>這一版本也聲稱改進了對 HDPI 顯示的支持。然而，結合 GNOME 和 Unity 對 HDPI 的支持，實際經驗是憂喜參半的。特別是字體渲染遠不及 OS X 所提供的渲染平滑。對我來説，即使安裝 了 Infinality 並進行調整，也從來沒有出現令我滿意的結果。我們仍然不確定問題是否是在安裝過程中出現的，並且我們也未親眼見到 HDPI 的新功能。或許，KDE 對於究竟是什麼構成了 HDPI 支持有一個完全不同的定義。但願問題是出在安裝過程中。</p><h3 id="有哪些缺陷" tabindex="-1">有哪些缺陷 <a class="header-anchor" href="#有哪些缺陷" aria-label="Permalink to “有哪些缺陷”">​</a></h3><p>在本文的前半部分，我們曾提到由 KDE 4 向 Plasma 5 的轉變將不會像從 KDE 3 向 KDE 4 的轉變那樣艱難。對大多數人來説，這是真的，但是，對於某些人來説，也許會出現例外。</p><p>KDE 項目稱這一版本的焦點已經“集中在了彌補核心工作流的工具上”，並表明“並不是所有 Plasma 4 系列中的功能都可以使用了”。這給那些經歷了 KDE 3 向 KDE 4 轉變的人敲響了警鐘。</p>',19)),n("p",null,[e[13]||(e[13]=a("在測試期間，我們並未遇到任何性能上的差距或者功能上的顯著缺失，除了提到：Breeze 主題的不完善、某些圖形故障，以及某些可疑的設計方面的問題。也就是説，請查閲",-1)),p(t,{href:"https://community.kde.org/Plasma/5.0_Errata"},{default:s(()=>[...e[12]||(e[12]=[a("已知問題列表",-1)])]),_:1}),e[14]||(e[14]=a("，特別是性能方面的警示。",-1))]),e[34]||(e[34]=n("p",null,"同時我們在此建議在你完全遷移至 Plasma 5 之前請提前測試，以確保你所必需的都已具備。",-1)),e[35]||(e[35]=n("h3",{id:"結論",tabindex:"-1"},[a("結論 "),n("a",{class:"header-anchor",href:"#結論","aria-label":"Permalink to “結論”"},"​")],-1)),e[36]||(e[36]=n("p",null,"KDE Plasma 5 版本缺乏使 Unity 和 GNOME 一躍成名的那種吸引人的代表性變化。與之相反，KDE 項目致力於改善其核心桌面體驗。從任何意義上講 Plasma 5 都不是完美的，但與 Unity 和 GNOME 不同，你可以隨意改變那些你所不喜歡的地方。",-1)),e[37]||(e[37]=n("p",null,"這一版本最激動人心的地方在於 KDE 已經在完全沒有弄亂現有桌面的情況下，為交互界面做出了大量鋪墊。另一個好消息是速度方面的改善。如果你此前曾經嘗試過 KDE 並覺得它過於“龐大”，那麼你應該重新審視以下 Plasma 5 了。",-1)),e[38]||(e[38]=n("hr",null,null,-1)),n("p",null,[e[16]||(e[16]=a("via: ",-1)),p(t,{href:"http://arstechnica.com/information-technology/2014/08/kde-plasma-5-for-those-linux-users-undecided-on-the-kernels-future/"},{default:s(()=>[...e[15]||(e[15]=[a("http://arstechnica.com/information-technology/2014/08/kde-plasma-5-for-those-linux-users-undecided-on-the-kernels-future/",-1)])]),_:1})]),n("p",null,[e[19]||(e[19]=a("作者：Scott Gilbertson 譯者：",-1)),p(t,{href:"https://github.com/SteveArcher"},{default:s(()=>[...e[17]||(e[17]=[a("SteveArcher",-1)])]),_:1}),e[20]||(e[20]=a(" 校對：",-1)),p(t,{href:"https://github.com/wxy"},{default:s(()=>[...e[18]||(e[18]=[a("wxy",-1)])]),_:1})]),n("p",null,[e[23]||(e[23]=a("本文由 ",-1)),p(t,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...e[21]||(e[21]=[a("LCTT",-1)])]),_:1}),e[24]||(e[24]=a(" 原創翻譯，",-1)),p(t,{href:"http://linux.cn/"},{default:s(()=>[...e[22]||(e[22]=[a("Linux中國",-1)])]),_:1}),e[25]||(e[25]=a(" 榮譽推出",-1))])])}const x=r(m,[["render",d]]);export{g as __pageData,x as default};
